import { PrivateKey } from '../../../crypto/common';
import { generateSignKeyFromDER } from '../../../crypto/crypto_explore_certificate';

// Self-signed ECC fixtures generated with:
//   openssl ecparam -name prime256v1 -genkey -noout -out p256.key.pem
//   openssl req -new -x509 -key p256.key.pem -out p256.cert.pem -days 365 -sha256 \
//     -subj "/CN=ecc-p256-test" -addext "subjectAltName=URI:urn:test:ecc-p256" \
//     -addext "basicConstraints=critical,CA:FALSE" \
//     -addext "keyUsage=critical,digitalSignature,nonRepudiation,keyAgreement"
//   openssl x509 -in p256.cert.pem -outform DER -out p256.cert.der
//   openssl pkcs8 -topk8 -nocrypt -in p256.key.pem -outform DER -out p256.key.der
// (secp384r1 / -sha384 for the P-384 pair.)
const P256_CERT_HEX =
  '';
const P256_KEY_HEX =
  '308187020100301306072a8648ce3d020106082a8648ce3d030107046d306b0201010420e15a9b4d885c7f24d4bb622feb875ca40b6ac9fedcbc6e5d5318d717ae5ae37ca144034200045565fd9a45a492bb381a60fcc2c841de7481667d0dd100f0d81d56f71f043de5475821bff321203df954606041b1b53d31094f320552dba8cb7e4612080c873e';
const P384_CERT_HEX =
  '';
const P384_KEY_HEX =
  '';

export type EccFixtureCurve = 'P-256' | 'P-384';

export function eccFixtureCertDer(curve: EccFixtureCurve): Uint8Array {
  return Uint8Array.fromHex(curve === 'P-256' ? P256_CERT_HEX : P384_CERT_HEX);
}

export function eccFixtureKeyDer(curve: EccFixtureCurve): Uint8Array {
  return Uint8Array.fromHex(curve === 'P-256' ? P256_KEY_HEX : P384_KEY_HEX);
}

/** PrivateKey backed by the fixture PKCS#8 key (ECDSA sign path). */
export function eccFixturePrivateKey(curve: EccFixtureCurve): PrivateKey {
  const keyDer = eccFixtureKeyDer(curve);
  return {
    getDecryptKey: () => Promise.reject(new Error('ECC has no RSA decrypt')),
    getSignKey: (hash) =>
      generateSignKeyFromDER(
        keyDer,
        hash,
        'ECDSA',
        curve
      ) as Promise<CryptoKey>,
  };
}
